	@Override
	public long sessionElapsedSeconds()
	{
		if (sessionStartMs <= 0 || client == null
			|| client.getGameState() != GameState.LOGGED_IN)
		{
			return 0;
		}
		return Math.max(0, (System.currentTimeMillis() - sessionStartMs) / 1000L);
	}

