	private static final int SLAYER_TASK_CAP = 1000;

	private JsonObject slayerRoot()
	{
		JsonObject sl = sub(root, "slayer");
		if (!sl.has("tasks") || !sl.get("tasks").isJsonArray())
		{
			sl.add("tasks", new JsonArray());
		}
		return sl;
